#pragma once
// Bluetooth/WiFi paths: Lucide Icons, ISC; see docs/licenses/Lucide-ISC.txt.
#define OFE_TRANSPORT_HEADER_HTML R"ICON(<span class="transport-icons"><a class="transport-ble" href="/display-link#ble" title="Bluetooth" aria-label="Bluetooth"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m7 7 10 10-5 5V2l5 5L7 17"/></svg></a><a class="transport-wifi" href="/config" title="WLAN / WiFi" aria-label="WLAN / WiFi"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h.01"/><path d="M2 8.82a15 15 0 0 1 20 0"/><path d="M5 12.859a10 10 0 0 1 14 0"/><path d="M8.5 16.429a5 5 0 0 1 7 0"/></svg></a></span>)ICON"
#define OFE_TRANSPORT_HEADER_SCRIPT R"ICONS(<style>.brand{flex-wrap:wrap;min-width:0}.brand .transport-icons{display:inline-flex;align-items:center;gap:4px;margin:0}.transport-icons a{display:inline-flex;align-items:center;justify-content:center;width:32px;height:36px;color:#7b8794;text-decoration:none}.transport-icons .transport-ble.is-on{color:#69b4ff}.transport-icons .transport-wifi.is-on{color:#59c77a}.transport-icons a:hover{color:#fff}</style><script>(()=>{async function update(){if(document.hidden)return;try{const r=await fetch('/display-link/ble?brief=1',{cache:'no-store'});if(!r.ok)return;const s=await r.json();document.querySelectorAll('.transport-ble').forEach(e=>e.classList.toggle('is-on',!!s.active));document.querySelectorAll('.transport-wifi').forEach(e=>e.classList.toggle('is-on',!!s.wifi));}catch(e){}}update();setInterval(update,5000);})();</script>)ICONS"
